# Receipt counters independently verify effective A+ readout branch.
receipts=[]
for group,root in [('R7_primary30','research/research_max_struct_r7/RESULTS/primary'),('R8_all_available_EXECUTION_not_independent_objects','research/research_max_struct_r8/RESULTS'),('R13_mechanism16','research/research_max_struct_r13/RESULTS/confirmation_mechanism16'),('R13_extension32','research/research_max_struct_r13/supplement_aplus48/RESULTS')]:
 for p in sorted(Path(root).rglob('AUXILIARY_EXECUTION.json')):
  if 'a_plus' not in str(p):continue
  d=json.loads(p.read_text());c=d.get('operation_counts',{})
  def line(key):
   return next((i for i,l in enumerate(p.read_text().splitlines(),1) if '"'+key+'"' in l),None)
  z=dict(group=group,source_path=str(p),status=d.get('status'),sourcewise_cg=d.get('sourcewise_cg'),initialize_physical_current=d.get('initialize_physical_current'))
  for key in ['aplus_readouts','aplus_arc_stationary_roots','aplus_conditional_polynomial_roots','aplus_inherited_gtol_checks']:
   z[key]=c.get(key);z[key+'_line']=line(key)
  receipts.append(z)
with (OUT/'APLUS_RECEIPT_COUNTERS.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=list(receipts[0]));w.writeheader();w.writerows(receipts)
summary=[]
for group in dict.fromkeys(x['group'] for x in receipts):
 rs=[x for x in receipts if x['group']==group]
 summary.append(dict(group=group,execution_receipts=len(rs),arc_root_receipts=sum(bool(x['aplus_arc_stationary_roots']) for x in rs),quintic_root_receipts=sum(bool(x['aplus_conditional_polynomial_roots']) for x in rs),guard_receipts=sum(bool(x['aplus_inherited_gtol_checks']) for x in rs),arc_roots_total=sum(x['aplus_arc_stationary_roots'] or 0 for x in rs),quintic_roots_total=sum(x['aplus_conditional_polynomial_roots'] or 0 for x in rs),guard_checks_total=sum(x['aplus_inherited_gtol_checks'] or 0 for x in rs)))
(OUT/'APLUS_VERSION_RECEIPT_SUMMARY.json').write_text(json.dumps(summary,indent=2)+'\n')
print('ledger_rows',len(rows),'receipt_rows',len(receipts));print(json.dumps(summary,indent=2))
